const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'dispatch') throw new Error('unsupported_resource');
const recordId = text(fields.order_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const action = text(fields.action);
if (!['start', 'arrive'].includes(action)) throw new Error('invalid_dispatch_action');
const allowed = new Set(['order_id', 'action', 'note']);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const note = text(fields.note);
if (note.length > 4000) throw new Error('note_max_4000');
const audit = {
  product, resource, operation: 'dispatch.progress', recordId, action,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};
return { recordId, encodedOrderId: encodeURIComponent(recordId), action, note, audit };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('order_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const order = { ...current.data, id: String(current.data.id || current.id) };
const status = String(order.status);
// Responder progression (mirrors dispatch_action at routes:1374-1375): an
// assigned unit starts en route, then arrives on scene.
const progression = {
  start: { next: 'in_transit', allowedFrom: ['assigned'], timestamp: 'started_at' },
  arrive: { next: 'on_scene', allowedFrom: ['in_transit'], timestamp: 'arrived_at' },
};
const rule = progression[state.action];
if (!rule) throw new Error('invalid_dispatch_action');
if (status === rule.next) return { idempotent: true, order_id: order.id, status, action: state.action, operation: state.operation };
if (['completed', 'canceled', 'rejected'].includes(status)) throw new Error('order_terminal');
if (!rule.allowedFrom.includes(status)) throw new Error('invalid_dispatch_transition');
const history = Array.isArray(order.status_history) ? [...order.status_history] : [];
history.push({ from: status, to: rule.next, action: state.action, at: $now, by: state.audit.submittedBy, note: state.note || null });
const next = { ...order, status: rule.next, status_history: history, updated_at: $now };
next[rule.timestamp] = $now;
return { body: { data: next, ifVersion: current.version }, encodedId: state.encodedOrderId, audit: state.audit, operation: state.operation };

const state = $input || {};
if (state.idempotent !== true) throw new Error('unexpected_progression_mode');
return { idempotent: true, operation: 'dispatch.progress', order_id: state.order_id, status: state.status, action: state.action };
